import sys; sys.path.insert(0,'/home/claude/scripts')
from facts_lib import save
N="تعليمات منح درجة البكالوريوس في تخصص دكتور في الطب"
save("0216",N,[
("rule",[1],"المادة 2 و3","تسري أحكام هذه التعليمات على الطلبة المنتظمين المسجلين للحصول على درجة البكالوريوس في تخصص دكتور في الطب، إلا فيما يخص توزيع المساقات وما يتعلق بها من ترفيع أو رسوب فيكون حسب الخطة التي يدرس عليها الطالب. ويقر مجلس العمداء الخطة الدراسية وأي تعديل عليها بناءً على توصية مجلس كلية الطب وتنسيب لجنة الخطة الدراسية في الجامعة.",
 "على من تسري تعليمات منح درجة البكالوريوس في تخصص دكتور في الطب ومن يقر الخطة الدراسية؟","ما الاستثناء من سريان التعليمات فيما يخص توزيع المساقات والترفيع والرسوب؟","مين بقر الخطة الدراسية للطب وعلى مين بتسري التعليمات؟"),
("rule",[1],"المادة 4","توضع الخطة الدراسية على أساس النظام السنوي في جميع سنوات الدراسة لنيل درجة البكالوريوس في تخصص دكتور في الطب، ومساقات السنوات إجبارية للطلبة كما في الخطة. ويحدد لكل مساق ساعات معتمدة خاصة به ورقم خاص، ويذكر إزاءه عدد الساعات المعتمدة وعدد المحاضرات أو ساعات المختبر الأسبوعية أو ساعات التدريب الميداني أو أسابيع التدريب السريري ومدة دراسته في السنة، وتكون نتائج المساق فصلية أو سنوية.",
 "على أي نظام توضع الخطة الدراسية لدكتور في الطب وهل المساقات إجبارية؟","ما البيانات التي تذكر إزاء كل مساق في الخطة الدراسية للطب؟","خطة الطب سنوية ولا فصلية؟ وهل فيها مواد اختيارية؟"),
("rule",[2],"المادة 6 (أ-1)","تخصص لمتطلبات الجامعة في خطة دكتور في الطب 25 ساعة معتمدة، وتطبق على المقبولين اعتباراً من العام الجامعي 2021/2022 فما بعد، أما الطلبة القدامى فحسب ما نصت عليه الخطة. وتخصص للمتطلبات الإجبارية 16 ساعة معتمدة، وهي: اللغة العربية ومهارات الاتصال والتواصل (ع102) 3 ساعات، القيادة والمسؤولية المجتمعية (ع أ110) 3، الريادة والابتكار (ع أ119) 2، اللغة الإنجليزية ومهارات الاتصال والتواصل (ل غ101) 3، المهارات الحياتية (ل غ103) 2، العلوم العسكرية (ع ع100) 3.",
 "كم ساعة معتمدة لمتطلبات الجامعة في خطة دكتور في الطب وما المتطلبات الإجبارية منها؟","ما المساقات الإجبارية من متطلبات الجامعة لطلبة الطب وكم ساعتها؟","كم ساعة متطلبات جامعة بالطب وأي مواد إجبارية؟"),
("rule",[2],"المادة 6 (أ-1) ملاحظات","يشترط للتسجيل في مساق اللغة الإنجليزية ومهارات الاتصال والتواصل (ل غ101) النجاح في ل غ99 أو اجتياز امتحان المستوى بعلامة 50% على الأقل. ويجوز للطلبة غير الأردنيين أخذ مساق بديل عن العلوم العسكرية من مساقات الجامعة الاختيارية. وكانت نتائج العلوم العسكرية نجاحاً ورسوباً حتى الفصل الصيفي 2016/2017 على أن تدخل نقاطه في حساب معدلات المقبولين اعتباراً من العام 2017/2018. ويدرس الطلبة غير الناطقين بالعربية (ع102أ) و(ع أ110أ) بدل (ع102) و(ع أ110).",
 "ما شرط التسجيل في ل غ101 لطلبة الطب وهل يعفى غير الأردنيين من العلوم العسكرية؟","أي مساقات يدرسها الطلبة غير الناطقين بالعربية بدلاً من ع102 وع أ110؟","أنا غير أردني، لازم أدرس علوم عسكرية؟ وكيف الطلاب الأجانب بدرسوا عربي؟"),
("rule",[2],"المادة 6 (أ-2)","تخصص للمتطلبات الاختيارية من متطلبات الجامعة تسع ساعات معتمدة، يختار الطالب منها ثلاث ساعات فقط من كل مجموعة من ثلاث مجموعات (المعارف الإنسانية وغيرها)، وتحسب جميع هذه المساقات من مستوى سنة أولى بغض النظر عن رقم سطر المساق.",
 "كم ساعة اختيارية لمتطلبات الجامعة في الطب وكيف تتوزع على المجموعات؟","كيف تحسب المساقات الاختيارية للجامعة من حيث المستوى في خطة الطب؟","كم مادة اختيارية جامعة لازم آخذ وكيف؟"),
("rule",[3],"المادة 7 (هـ، و)","تتكون كل سنة من السنتين الأولى والثانية من فصلين دراسيين مدة كل منهما 16 أسبوعاً بما في ذلك الامتحانات، ومن فصل صيفي مدته 8 أسابيع بما في ذلك الامتحانات. وتتكون السنة الثالثة من فصلين دراسيين مدة كل منهما 16 أسبوعاً بما في ذلك الامتحانات.",
 "كم أسبوعاً مدة الفصل الدراسي في السنتين الأولى والثانية من الطب وكم مدة الصيفي؟","هل في فصل صيفي في السنة الثالثة بالطب وكم مدة فصلها؟","كم مدة الفصل والصيفي بالسنة الأولى والثانية بالطب؟"),
("rule",[3],"المادة 7 (ز، ح، ط، ي)","يعرّف مجلس الكلية السنة السريرية للسنوات السريرية المتصلة بموجب تقويم زمني يقره في مطلع كل عام جامعي. وتبدأ الدراسة لطلبة السنتين الأولى والثانية في شهر أيلول وتنتهي في شهر آب، ولطلبة السنة الثالثة تبدأ في أيلول وتنتهي في أيار من العام الذي يليه، ولطلبة السنوات الرابعة والخامسة والسادسة تبدأ في حزيران وتنتهي في أيار من العام الذي يليه.",
 "متى تبدأ وتنتهي الدراسة لكل سنة من سنوات الطب؟","في أي شهر تبدأ الدراسة للسنوات الرابعة والخامسة والسادسة في الطب؟","السنة الرابعة بالطب بتبدأ أي شهر وبتخلص أي شهر؟"),
("rule",[3],"المادة 7 (ك، م، ن)","لا يجوز أن يسجل الطالب للمساق العلمي أكثر من مرة في نفس المستوى، وفي حال عدم الالتزام يعتبر تسجيله وعلامته في ذلك المساق لاغيين. ولمجلس العمداء منح الطالب سنة دراسية لإنهاء متطلبات الدرجة زيادة عن المدة القصوى شريطة أن تؤدي هذه السنة إلى تخرجه. ولا يجوز للطالب تسجيل أو دراسة مساق أعفي من دراسته لأي سبب.",
 "هل يجوز تسجيل المساق العلمي أكثر من مرة في نفس المستوى في الطب؟","هل يمكن لمجلس العمداء منح الطالب سنة زائدة عن المدة القصوى؟","بقدر أدرس مساق انعفيت منه؟"),
("rule",[3],"المادة 8 (أ)","تشترط المواظبة للطالب في جميع المساقات التي يسجل فيها، ويدخل مدرس المساق الغياب على نظام الغياب الإلكتروني بشكل دوري خلال عشرة أيام من موعد الغياب، وتحسب نسبة الغياب على المحاضرات الوجاهية للمساقات الوجاهية أو المدمجة، وعلى المحاضرات متزامنة الحضور للمساقات الإلكترونية، ويبلغ الطالب إلكترونياً بشكل دوري.",
 "خلال كم يوماً يدخل المدرس الغياب على النظام الإلكتروني في كلية الطب؟","على أي محاضرات تحسب نسبة الغياب في المساقات الوجاهية والإلكترونية؟","كيف بتتحسب نسبة غيابي بالطب؟"),
("rule",[3],"المادة 8 (ب)","إذا غاب الطالب أكثر من 20% من مجموع ساعات المساق بغض النظر عن السبب، يحرم من التقدم لجميع الامتحانات اللاحقة ويوضع له الرمز «هـ» (محروم بسبب الغياب) وتدخل نقاط المساق في معدله السنوي، ويسمح له بالتقدم لامتحان إكمال (للمساق العلمي فقط) على أن يعوض التدريب السريري لكافة أيام الغياب في السنتين الرابعة والخامسة، ويعوض التدريب السريري كاملاً (100%) للسنة السادسة. ولعميد الكلية تجاوز غياب 20% بعذر قهري يقبل به على ألا يتجاوز مجموع الغيابات 30%.",
 "ماذا يحدث لطالب الطب إذا زاد غيابه عن 20% من المساق وكيف يعوض التدريب السريري؟","ما أقصى نسبة غياب يمكن لعميد الكلية تجاوزها بعذر قهري؟","غبت أكثر من 20% بالطب، شو بصير؟ وبقدر العميد يسامحني؟"),
("rule",[3],"المادة 8 (ج، د)","في الحالات التي يتجاوز فيها غياب الطالب 20% بعذر مقبول لمجلس كلية الطب اعتباره منسحباً من السنة الدراسية (بدون ترصيد الرسوم) ابتداء من الفصل الذي تغيب به، ويبلغ العميد المسجل العام قبل بدء الامتحانات النهائية وتعتبر دراسته مؤجلة لتلك السنة. ولا يجوز الانسحاب من المساقات العلمية (المرفعة)، وتطبق تعليمات البكالوريوس المعدلة بشأن الانسحاب من المساقات على متطلبات الجامعة فقط.",
 "ماذا يقرر مجلس كلية الطب إذا تجاوز الغياب 20% بعذر مقبول؟","هل يجوز الانسحاب من المساقات العلمية المرفعة في الطب؟","غبت كثير بعذر مقبول، بيعتبروني منسحب؟ وبقدر أنسحب من مساق علمي؟"),
("rule",[3],"المادة 8 (هـ، ز)","إذا انقطع الطالب عن التدريب العملي لفترة لا تتجاوز 25% من مدة التدريب لعذر قهري أو مرضي يقبل به عميد الكلية، يجوز للعميد السماح له بتعويض فترة الغياب إذا رأى أنه لا يؤثر فنياً على التدريب، ولا يشمل ذلك العمل في المستشفيات والعيادات الذي يتم بإشراف أعضاء الهيئة التدريسية. والمدرسون ورؤساء الأقسام وعميد الكلية مسؤولون عن تنفيذ أحكام المواظبة.",
 "هل يمكن تعويض الانقطاع عن التدريب العملي في الطب وبأي نسبة؟","من المسؤول عن تنفيذ أحكام المواظبة في كلية الطب؟","انقطعت عن التدريب العملي بعذر، بقدر أعوض؟"),
("rule",[4],"المادة 9 (أ، ب-1)","تحسب العلامات الفصلية أو السنوية وعلامة الامتحان النهائي والعلامة النهائية المستحقة لأقرب رقم صحيح، وتكون العلامة النهائية من مائة ثم تحول إلكترونياً إلى رمز وما يكافئه من نقاط حسب جدول المادة 11 (أ). والعلامة النهائية لكل مساق هي مجموع علامات الامتحان النهائي وعلامات الأعمال الفصلية، وقد تكون نتيجة بعض المساقات ناجح أو راسب كما في الخطة.",
 "كيف تحسب العلامة النهائية للمساق في الطب وإلى أي رقم تقرب؟","هل كل المساقات في الطب لها علامة رقمية أم تكون بعضها ناجح/راسب؟","العلامة النهائية بالطب من كم وكيف بتتقرب؟"),
("rule",[4],"المادة 9 (ب-2، ب-3)","يعقد الامتحان النهائي لكل مساق مرة واحدة إما في نهاية الفصل أو في نهاية السنة حسب طبيعة المساق، ويكون كتابياً أو محوسباً وشاملاً لمقرر المساق، ويجوز أن يشمل جزءاً شفوياً أو عملياً أو تقارير لها نسبة معينة. وتشمل الأعمال الفصلية أو السنوية الاختبارات الشفوية أو التقارير أو البحوث أو المتطلبات السريرية، وامتحانات فصلية أو سنوية يعلن عنها قبل أسبوع على الأقل وتناقش إجاباتها وترد النتائج خلال أسبوع من عقد الامتحان، وتقاييم الانضباط والسلوك والمواظبة وفق آليات تعلن في الأسبوع الأول من بدء المساق.",
 "ماذا تشمل الأعمال الفصلية للمساق في الطب وخلال كم تعلن الامتحانات وترد النتائج؟","كم مرة يعقد الامتحان النهائي لكل مساق وما شكله؟","قبل كم بيعلنوا عن الامتحان الفصلي وخلال كم بيرجعوا الأوراق؟"),
("rule",[4],"المادة 9 (ب-5)","على المدرسين إدخال علامات الأعمال الفصلية ونشرها للطلبة في موعد أقصاه نهاية الأسبوع الثالث عشر من الفصلين الأول والثاني ونهاية الأسبوع السابع للفصل الصيفي، ويعتمدها مدرس المساق في موعد أقصاه نهاية الأسبوع الخامس عشر. ولعميد الكلية صلاحية فك اعتماد الأعمال الفصلية حتى نهاية الامتحانات النهائية، وتوثق كافة الحركات على العلامات من تحميلها حتى اعتمادها ويحق للعميد مشاهدتها، ويتم تعديل أي علامة بعد انتهاء الفصل عن طريق إجراء تعديل العلامات.",
 "متى يجب على المدرسين إدخال ونشر علامات الأعمال الفصلية واعتمادها في الطب؟","من يملك صلاحية فك اعتماد الأعمال الفصلية وحتى متى؟","آخر موعد لنشر علامات الأعمال الفصلية متى؟"),
("rule",[4],"المادة 9 (ب-6، ب-7، ب-8) تفصيل","إذا لم يتم الطالب متطلبات مساق أو تغيب عن الامتحان النهائي بعذر قهري أو مرضي يقبل به عميد الكلية، تسجل له نتيجة «غير مكتمل» وتعقد الامتحانات خلال الأسبوعين الأول والثاني من بدء الفصل اللاحق (وللصيفي قبل بدء الفصل الأول من العام التالي)، ويعتمد المدرس العلامات خلال 48 ساعة من الامتحان ورئيس القسم خلال 24 ساعة ثم العميد خلال 24 ساعة. وإذا تغيب عن الامتحان التكميلي ترصد له علامة صفر في الامتحان النهائي. ولا يجوز للحاصل على غير مكتمل تأجيل دراسته إلا بعد إزالة الملاحظة وإلا ترصد له علامة الأعمال الفصلية.",
 "ما مدد اعتماد علامات امتحان غير المكتمل في الطب وماذا يحدث لو تغيب عنه؟","هل يجوز تأجيل الدراسة لمن عنده «غير مكتمل»؟","غبت عن النهائي بعذر وصار عندي غير مكتمل، شو أعمل؟"),
("rule",[4],"المادة 9 (ب-4) تفصيل","إذا تغيب الطالب عن الامتحان الفصلي أو السنوي فعليه تقديم عذر قهري أو مرضي لرئيس القسم أو منسق المساق (لمساقات الأجهزة)، وينظر في اعتماد العذر خلال 48 ساعة من انتهاء أسبوع التقديم، ويبدأ عقد امتحان تكميلي في حال قبول العذر خلال مدة أقصاها 72 ساعة من تاريخ موافقة رئيس القسم، وإلا يوضع له صفر في ذلك الامتحان ويحسب في العلامة النهائية.",
 "كم المدة لاعتماد عذر الغياب عن الامتحان الفصلي في الطب وموعد الامتحان التكميلي؟","ماذا يوضع للطالب الذي غاب عن امتحان فصلي بدون عذر مقبول؟","تغيبت عن الامتحان الفصلي، متى بعرفوا إذا عذري مقبول وكيف التكميلي؟"),
("rule",[4],"المادة 9 (ج-1) تفصيل","للمقبولين اعتباراً من 2018/2019 في مساقات الكلية للسنوات الأولى والثالثة (غير الأجهزة)، النظرية وما يحوي جزءاً عملياً: 60% للأعمال الفصلية (اختباران فصليان 30 علامة لكل منهما، قد تكون تحريرية أو شفوية أو عملية أو حاسوبية أو تقارير) و40% للامتحان النهائي. أما مساقات الأجهزة في السنتين الثانية والثالثة ومساقات ط173 وط183 وط284 وط293 وط301 وط312 فـ60% للامتحان النصفي (الجزء النظري) و40% للنهائي (العملي والسريري). وتوزع علامات المساقات العملية حسب ما يبينه مجلس القسم قبل بداية الفصل.",
 "كيف توزع علامات المساقات النظرية في السنوات الأولى إلى الثالثة بالطب؟","كيف توزع علامات مساقات الأجهزة وط173 وط183 وط284 وط293 وط301 وط312؟","نسبة الأعمال الفصلية والنهائي بمواد السنة الثانية بالطب كم؟"),
("rule",[4],"المادة 9 (ج-2)","في السنتين الرابعة والخامسة للمساقات التي تقل ساعاتها عن 9 ساعات (عدا ط408 طب المجتمع ومشروع بحث): 20% لتقييم مدرسي المساق أثناء التدريب السريري (انضباط وسلوك ومواظبة ومشاريع بحثية وريادية)، و40% للامتحان السريري بعد نهاية الدورة (حالات طويلة وقصيرة أو شفوي أو OSCE أو محاكاة)، و40% للامتحان الكتابي أو المحوسب. أما ط408 فـ40% للجزء العملي و60% للنهائي. وللمساقات ذات 9 ساعات: 20% و40% للامتحان السريري و40% للكتابي الذي يعقد مرة واحدة في نهاية العام لجميع الطلبة بعد التدريب السريري.",
 "كيف توزع علامات مساقات السنتين الرابعة والخامسة في كلية الطب؟","كيف توزع علامات مساق ط408 طب المجتمع ومشروع بحث؟","شو نسبة الامتحان السريري والكتابي بالسنة الرابعة؟"),
("rule",[4],"المادة 9 (ج-2، ج-3) تتمة","مساقات ط591 وط592 (تدريب اختياري) وط420 (أبحاث) تكون نتيجتها نجاح ورسوب. ومساقات السنة السادسة توزع علاماتها: 50% للأعمال الفصلية (20% لتقييم المدرسين أثناء التدريب السريري و30% للامتحان السريري) و50% للامتحان النهائي (40% كتابي أو محوسب و10% شفوي).",
 "ما المساقات التي نتيجتها نجاح/رسوب في خطة الطب؟","كيف توزع علامات السنة السادسة في كلية الطب؟","ط420 وط591 كيف بتتصحح؟ وعلامات السادسة كيف؟"),
("rule",[5],"المادة 10 (أ، ج، هـ)","على مدرس المساق إعلام طلبته مع بداية كل فصل بأسلوب تقييم التحصيل. ويعتمد عميد الكلية أو من ينوب عنه النتائج النهائية لجميع المساقات إلكترونياً بعد البت فيها مباشرة. وتناقش جميع أوراق الامتحانات والتقارير والبحوث مع الطالب بعد تصحيحها، وتحفظ أوراق الامتحان النهائي لدى عمادة الكلية لمدة فصل دراسي واحد ثم يتصرف بها العميد.",
 "كم تحفظ أوراق الامتحان النهائي في كلية الطب؟","من يعتمد النتائج النهائية لجميع المساقات في الكلية؟","كم مدة حفظ ورقة الامتحان النهائي عند العمادة؟"),
("rule",[5],"المادة 10 (د) تفصيل","يحق للطالب (بعد دفع الرسوم) أو المدرس طلب مراجعة علامة الامتحان النهائي (خطياً أو إلكترونياً) خلال 6 أسابيع كحد أقصى من الفصل اللاحق. تشكل لجنة داخلية لا يكون مدرس المساق عضواً فيها وتعتمد الحل المثالي المقدم منه ويعتمد رئيس القسم والعميد القبول أو الرفض، وتعرض الطلبات المقبولة على اللجنة العليا لتعديل العلامات، ويعدل الوضع الأكاديمي بأثر رجعي. ويفقد الطالب حقه إذا أجل دراسته للفصل اللاحق.",
 "ما إجراءات طلب مراجعة علامة الامتحان النهائي في الطب ومن يقرر؟","متى يفقد الطالب حقه في طلب تعديل العلامة؟","بدي أراجع علامتي، كم عندي وقت وشو الإجراءات؟"),
("rule",[6],"المادة 12","يعين مجلس القسم أحد مدرسي المساق منسقاً إذا كان يدرس من أكثر من مدرس أو متعدد الشعب، بالتعاون مع بقية المدرسين وبإشراف رئيس القسم. ويتولى رئيس القسم أو منسق المساق أو من يختاره المجلس الإشراف على طباعة الأسئلة بعد إقرارها من مجلس القسم وعلى تصحيح الأوراق ونقل النتائج إلى الكشوفات بالشكل الصحيح.",
 "من يعين منسق المساق متعدد المدرسين أو الشعب في كلية الطب وما مهامه؟","من يشرف على طباعة أسئلة الامتحانات ونقل النتائج في المساقات متعددة الشعب؟","مين بنسق المساق اللي بيدرسه كذا مدرس؟"),
("rule",[6],"المادة 13 (أ-ج، هـ)","الحد الأدنى لرمز النجاح في كل مساق هو (د-)، والحد الأدنى للنجاح في المعدلات السنوية 2.00 وفي المعدل العام 2.00، ورمز الرسوب (هـ)، ويحسب المعدل السنوي أو العام لأقرب منزلتين عشريتين. ويتكون المعدل العام لطلبة 2007 فما قبل من 60% للمعدل السنوي للسنوات الخمس الأولى بالتساوي (12% لكل سنة) و40% للسنة السادسة.",
 "ما الحد الأدنى للنجاح في المساق والمعدل السنوي والعام في الطب؟","كيف يحسب المعدل العام لطلبة الطب من 2007 فما قبل؟","شو أقل رمز نجاح بالطب وكيف بيتحسب المعدل للقدامى؟"),
("rule",[6],"المادة 13 (و) تفصيل","لطلبة 2008 فما بعد المعدل العام من 70% للمعدل السنوي للسنوات الخمس الأولى بالتساوي (14% لكل سنة) و30% للسنة السادسة. وللمسجلين للعام 2020/2019 إذا اعتمدت نتيجة السادسة (ناجح بدون معدل): 16% لكل من الأولى والثانية والثالثة و20% للرابعة و32% للخامسة مع اعتماد الأعلى بين ذلك والمتوسط الحسابي للسنوات الخمس. وإذا اعتمدت الخامسة: 15% للأولى والثانية والثالثة و20% للرابعة و35% للسادسة. وإذا اعتمدت الرابعة: 14% للأولى والثانية والثالثة و21% للخامسة و37% للسادسة.",
 "كيف يحسب المعدل العام لطلبة الطب المقبولين من 2008 فما بعد؟","كيف يحسب المعدل العام لمن اعتمدت لهم نتيجة السنة السادسة أو الخامسة أو الرابعة «ناجح بدون معدل سنوي» في 2019/2020؟","أوزان السنوات بالمعدل العام للطب كم؟"),
("rule",[6],"المادة 14","يحسب المعدل السنوي للسنة الأولى بضرب نقاط كل مساق مقر في الخطة الاسترشادية للسنة الأولى في ساعاته المعتمدة وقسمة المجموع على مجموع الساعات. وتدخل نتائج جميع مساقات متطلبات الجامعة (الإجبارية والاختيارية) في خطته في حساب المعدل السنوي للسنة الأولى، ويحسب معدل سنوي للسنوات الثلاث الأولى إذا بلغت الساعات المحتسبة فيه 12 ساعة معتمدة فأكثر، وإذا أعاد الطالب دراسة مساق منها يحسب له الرمز الأعلى.",
 "كيف يحسب المعدل السنوي للسنة الأولى في الطب وهل تدخل متطلبات الجامعة؟","متى يحسب معدل سنوي للسنوات الثلاث الأولى وماذا يحسب إذا أعاد مساقاً؟","شو شرط حساب المعدل السنوي بالسنة الأولى من الطب؟"),
("rule",[6],"المادة 15","يحسب المعدل السنوي للسنوات الخمس التالية (من الثانية إلى السادسة) بضرب نقاط كل مساق (عدا متطلبات الجامعة) في ساعاته المعتمدة المقرة في الخطة لتلك السنة وقسمة مجموع الحواصل على مجموع الساعات المعتمدة لتلك السنة.",
 "كيف يحسب المعدل السنوي من السنة الثانية حتى السادسة في الطب؟","هل تدخل متطلبات الجامعة في المعدل السنوي للسنوات الثانية إلى السادسة؟","كيف بنحسب المعدل السنوي بالسنة الثالثة؟"),
],"d",verified="text")
